{
  \"contract\": \"board-build-plan/v1\",
  \"artifacts\": [
    {
      \"alias\": \"title\",
      \"recipe\": {
        \"kind\": \"native_text\",
        \"text\": \"WILDFIRE RELIEF — COMMAND WORKFLOW\\nScan left → right. Red-route any unsafe, partial, blocked, or unverified outcome through EXCEPTION / FEEDBACK.\",
        \"placement\": { \"target\": { \"kind\": \"auto\" } }
      }
    },
    {
      \"alias\": \"field\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"1  FIELD REPORT\",
        \"body\": \"OWNER  Field Reporter / Liaison\\nCAPTURE  Location + callback • people at risk • fire/access conditions • requested aid • time + confidence\\nHANDOFF  Send only after coordinates and callback are confirmed\\nOUTPUT  Report ID + concise situation summary\"
      }
    },
    {
      \"alias\": \"triage\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"2  TRIAGE\",
        \"body\": \"OWNER  Triage Lead\\nDECIDE  P1 life safety • P2 time-sensitive • P3 routine\\nCHECK  Route safety • need validity • available capacity\\nHANDOFF  Priority + resources + due-by time + escalation trigger\"
      }
    },
    {
      \"alias\": \"dispatch\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"3  DISPATCH\",
        \"body\": \"OWNER  Operations / Dispatcher\\nASSIGN  Crew • vehicle • load • safe route • comms channel\\nCONFIRM  Crew acknowledgment + ETA\\nHANDOFF  Dispatch ID + assignment + check-in schedule\"
      }
    },
    {
      \"alias\": \"delivery\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"4  DELIVERY\",
        \"body\": \"OWNER  Crew Lead / Logistics\\nREPORT  Departed • arrived • quantities delivered • recipient\\nCAPTURE  Time + proof + unmet need or field change\\nHANDOFF  Delivery receipt + exceptions\"
      }
    },
    {
      \"alias\": \"verify\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"5  VERIFY & CLOSE\",
        \"body\": \"OWNER  Verification Officer\\nMATCH  Recipient • location • quantity • time • request ID\\nSTATUS  VERIFIED / PARTIAL / FAILED\\nHANDOFF  Close verified work; route every other status to EXCEPTION\"
      }
    },
    {
      \"alias\": \"exception\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"EXCEPTION / FEEDBACK — HOLD & DECIDE\",
        \"body\": \"OWNER  Safety Officer + Incident Commander\\nTRIGGER  Unsafe route • no contact • unavailable resource • mismatch • partial/failed delivery or verification\\nACTION  Hold movement • record reason • reroute/substitute/approve\\nRETURN  Updated facts and decision to TRIAGE; never silently close\"
      }
    },
    {
      \"alias\": \"closeout\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"INCIDENT COMMANDER — 30-SECOND SCAN\",
        \"body\": \"WATCH  Open P1s • unacknowledged dispatches • overdue ETAs • held exceptions • verification backlog\\nASK  What is blocked? Who owns it? What decision is due next?\\nDONE  Only when VERIFIED and logged against the original request\"
      }
    }
  ],
  \"connections\": [
    { \"kind\": \"visual\", \"label\": \"report ID + coordinates + callback\", \"source\": { \"alias\": \"field\" }, \"target\": { \"alias\": \"triage\" } },
    { \"kind\": \"visual\", \"label\": \"priority + resources + due-by\", \"source\": { \"alias\": \"triage\" }, \"target\": { \"alias\": \"dispatch\" } },
    { \"kind\": \"visual\", \"label\": \"crew ack + assignment + ETA\", \"source\": { \"alias\": \"dispatch\" }, \"target\": { \"alias\": \"delivery\" } },
    { \"kind\": \"visual\", \"label\": \"receipt + proof + unmet need\", \"source\": { \"alias\": \"delivery\" }, \"target\": { \"alias\": \"verify\" } },
    { \"kind\": \"visual\", \"label\": \"VERIFIED closeout\", \"source\": { \"alias\": \"verify\" }, \"target\": { \"alias\": \"closeout\" } },
    { \"kind\": \"visual\", \"label\": \"unsafe / capacity conflict\", \"source\": { \"alias\": \"triage\" }, \"target\": { \"alias\": \"exception\" } },
    { \"kind\": \"visual\", \"label\": \"no crew / blocked route\", \"source\": { \"alias\": \"dispatch\" }, \"target\": { \"alias\": \"exception\" } },
    { \"kind\": \"visual\", \"label\": \"partial / failed delivery\", \"source\": { \"alias\": \"delivery\" }, \"target\": { \"alias\": \"exception\" } },
    { \"kind\": \"visual\", \"label\": \"PARTIAL / FAILED verification\", \"source\": { \"alias\": \"verify\" }, \"target\": { \"alias\": \"exception\" } },
    { \"kind\": \"visual\", \"label\": \"reassess + re-prioritize\", \"source\": { \"alias\": \"exception\" }, \"target\": { \"alias\": \"triage\" } },
    { \"kind\": \"visual\", \"label\": \"decision required\", \"source\": { \"alias\": \"exception\" }, \"target\": { \"alias\": \"closeout\" } }
  ],
  \"layout\": {
    \"kind\": \"grid\",
    \"anchor\": { \"alias\": \"title\" },
    \"members\": [\"field\", \"triage\", \"dispatch\", \"delivery\", \"verify\", \"exception\", \"closeout\"],
    \"columns\": 5,
    \"column_gap\": 72,
    \"row_gap\": 96,
    \"align\": \"start\",
    \"placement\": { \"clearance\": 96, \"preferred_directions\": [\"below\"] }
  }
}
JSON"

